def check_k(k):
    # For a given k, we want to find if there is any set X with sum k and x_i <= 1
    # such that s_max < k - 6.
    # We test sets with m equal elements x = k/m.
    # The condition is s_max >= k-6, which is floor(1/x) * x >= k-6.
    # Since x = k/m, this is floor(m/k) * k/m >= k-6.

    for m in range(1, 100):
        x = k / m
        if x <= 1:
            s_max = (int(1 / x)) * x
            if s_max < k - 6:
                return False
    return True

# Test some values around 6.5
for k in [6.5, 6.51, 6.52, 6.53, 6.54, 6.55, 6.6]:
    print(f"k = {k}: {check_k(k)}")
